-- Total transactions
SELECT COUNT(*) AS Total_Trasaction FROM salesdata;

-- average transaction value?
SELECT AVG(Sales) AS Total_Trasaction FROM salesdata;

-- What is the total revenue generated by the company?
SELECT SUM(Sales) AS Total_Revenue FROM salesdata;

-- What is the total profit generated?
SELECT SUM(Profit) AS Total_Revenue FROM salesdata;

-- How many total products (units) were sold?
SELECT SUM(Quantity) AS Total_Revenue FROM salesdata;

-- How many unique products are available?
SELECT DISTINCT ProductName FROM salesdata;

-- What is the average sales value per transaction?
SELECT AVG(Sales) AS Avg_Sales_Value FROM salesdata;

-- What is the average profit per transaction?
SELECT AVG(Profit) AS Avg_Profit_per_Trasaction FROM salesdata;

-- What is the overall profit margin of the company?
SELECT
	SUM(Profit) AS Total_Profit,
    SUM(Sales) AS Total_Sales,
    ROUND((SUM(Profit) / NULLIF(SUM(Sales),0)) * 100,2) AS Overall_Profit_Margin
FROM salesdata;

-- What is the average selling value per unit?
SELECT
	SUM(Sales)/NULLIF(SUM(Quantity),0) AS Average_Selling_Value_Per_Unit
FROM salesdata;

-- What is the highest sales value recorded in a transaction?
SELECT MAX(Sales) AS Highest_Sale FROM salesdata;
-- What is the lowest sales value recorded in a transaction?
SELECT MIN(Sales) AS Lowest_Sale FROM salesdata;

USE ecommerce_sales_db;

